WITH flattened AS (SELECT id, service, log_ts, level, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, attr_value) SELECT level, COUNT(CASE WHEN level = 'WARN' THEN 1 END) AS warn_count, SORT_ARRAY(COLLECT_SET(key)) AS key_list, COUNT(CASE WHEN level = 'INFO' THEN 1 END) AS info_count, GROUPING(level) AS grouping_id FROM flattened GROUP BY CUBE (level) ORDER BY level DESC
